import math

def derangements(n):
    # D_n = n! * sum_{k=0}^n ((-1)^k / k!)
    if n == 0:
        return 1
    result = 0
    for k in range(n + 1):
        term = ((-1)**k) / math.factorial(k)
        result += term
    return round(math.factorial(n) * result)

print(derangements(16))

